using namespace std;

class Queue {
    int arr[MAX], front, rear, sz;
public:
    Queue() : front(0), rear(-1), sz(0) {}
    void enqueue(int x) { rear=(rear+1)%MAX; arr[rear]=x; sz++; }
    int dequeue() { int v=arr[front]; front=(front+1)%MAX; sz--; return v; }
    int getFront() { return arr[front]; }
    bool isEmpty() { return sz==0; }
};

